import re


def word_counts(text):
    counts = {}
    for word in re.findall(r'[a-z]+', text.lower()):
        counts[word] = counts.get(word, 0) + 1
    return list(counts.items())

import pytest
from words import word_counts


def test_canonical_equivalence_and_casefold():
    assert word_counts('Café CAFE\u0301 Straße STRASSE') == [('café', 2), ('strasse', 2)]


def test_scripts_numbers_and_boundaries():
    assert word_counts('中文 中文 １２ a_b a-b') == [('中文', 2), ('１２', 1), ('a', 2), ('b', 2)]


def test_input_type():
    with pytest.raises(TypeError):
        word_counts(None)

import unicodedata


def word_counts(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise TypeError("text must be a str")

    counts: dict[str, int] = {}
    current: list[str] = []

    def finish_word() -> None:
        if not current:
            return
        word = unicodedata.normalize("NFC", "".join(current))
        word = word.casefold()
        word = unicodedata.normalize("NFC", word)
        counts[word] = counts.get(word, 0) + 1
        current.clear()

    for char in text:
        category = unicodedata.category(char)
        kind = category[0]

        if kind in ("L", "N"):
            current.append(char)
        elif kind == "M":
            if current:
                current.append(char)
        else:
            finish_word()

    finish_word()
    return list(counts.items())
